import{_ as a,C as n,o as i,c as s,j as t,a as o,E as l,ak as h}from"./chunks/framework.BNVJvTzl.js";const w=JSON.parse(`{"title":"Every VERA feature, at one price","description":"Every VERA feature, included for everyone at one price set by your agency's revenue.","frontmatter":{"title":"Every VERA feature, at one price","description":"Every VERA feature, included for everyone at one price set by your agency's revenue."},"headers":[],"relativePath":"features.md","filePath":"features.md"}`),d={name:"features.md"};function g(c,e,u,p,y,m){const r=n("RevenuePicker");return i(),s("div",null,[e[3]||(e[3]=t("h1",{id:"features",tabindex:"-1"},[o("Features "),t("a",{class:"header-anchor",href:"#features","aria-label":'Permalink to "Features"'},"​")],-1)),t("p",null,[e[0]||(e[0]=o("Everything on this page is included for every agency on VERA. There are no feature tiers, no seat counts, and no usage charges for adding another project, client or invoice. You pay one monthly price set by your agency's annual revenue (",-1)),e[1]||(e[1]=t("a",{href:"/pricing.html"},"see Pricing",-1)),e[2]||(e[2]=o("), and everyone on your team gets all of it. ",-1)),l(r)]),e[4]||(e[4]=h('<h2 id="coming-from-harvest" tabindex="-1">Coming from Harvest? <a class="header-anchor" href="#coming-from-harvest" aria-label="Permalink to &quot;Coming from Harvest?&quot;">​</a></h2><p>Harvest is a good time tracker. If the per-seat bill, the plan you need for reports, or not knowing whether a project makes money has you looking around, see <a href="/harvest-alternative.html">how VERA compares with Harvest, and how switching works</a>.</p><h2 id="everything-vera-does" tabindex="-1">Everything VERA does <a class="header-anchor" href="#everything-vera-does" aria-label="Permalink to &quot;Everything VERA does&quot;">​</a></h2><h3 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h3><ul><li><strong>Log time in seconds.</strong> Pick the project and task, type the hours. No weekly grid to reconstruct on Friday afternoon.</li><li><strong>Quick-log from an allocation.</strong> One click logs against the work you were allocated.</li><li><strong>Log by Slack message</strong> for teams that live in Slack: &quot;4h on the Acme rebrand, design.&quot;</li><li><strong>Your week at a glance</strong>, with each day marked as worked, a holiday, a weekend or time off, and your total against what a normal week expects.</li><li><strong>Edit and delete your own entries</strong>, with every retroactive change recorded.</li><li><strong>A gentle evening reminder</strong> when you&#39;ve logged less than your normal day. Part-time schedules get their own target.</li><li><strong>Company holidays recorded automatically</strong> as paid time off for full-time staff once the day has passed.</li><li><strong>Time off</strong>: request PTO, see your history, withdraw a pending request.</li></ul><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><ul><li><strong>Every way agencies sell work</strong>: time and materials, fixed price, retainer, pro bono and internal.</li><li><strong>Revenue recognized the right way for each type</strong>: hours × rate, percentage of completion, or per retainer period.</li><li><strong>A burn-up chart</strong> of hours against budget, with the planned pace and the hours allocated.</li><li><strong>Schedule and budget health</strong> with the working shown: how many hours are recorded, what the plan expects by today, and how far off it is.</li><li><strong>Delivery view</strong>: planned against recorded hours for each person, week by week.</li><li><strong>Projected exhaustion</strong>: when the budget runs out at the current or planned pace.</li><li><strong>What this project needs</strong>: plain advice on the next thing to set up or fix, with a link to it.</li><li><strong>Change a project&#39;s type</strong> later, with its history recalculated.</li><li><strong>A billing schedule</strong> for fixed-price work, and a month-end view of scheduled against earned.</li></ul><h3 id="retainers" tabindex="-1">Retainers <a class="header-anchor" href="#retainers" aria-label="Permalink to &quot;Retainers&quot;">​</a></h3><ul><li><strong>Each period is its own window</strong>, with its own hours and contract value.</li><li><strong>Re-up in one click</strong> from the last period&#39;s terms.</li><li><strong>Judged on the period you&#39;re in</strong>, so last month&#39;s overrun can&#39;t hide this month&#39;s.</li><li><strong>Renewal reminders</strong> before a period ends with nothing lined up behind it.</li><li><strong>A different PM per period</strong> when the account changes hands.</li></ul><h3 id="allocations-and-capacity" tabindex="-1">Allocations and capacity <a class="header-anchor" href="#allocations-and-capacity" aria-label="Permalink to &quot;Allocations and capacity&quot;">​</a></h3><ul><li><strong>Allocate hours to a person, a project and a task</strong>, with as many allocations per person as the work needs.</li><li><strong>A window and a week-by-week shape</strong> for when the hours are expected to land.</li><li><strong>A capacity heatmap</strong>: everyone&#39;s committed hours against their availability, week by week, past weeks showing what was recorded.</li><li><strong>Time off and holidays counted</strong> in everyone&#39;s capacity.</li><li><strong>Overruns and unplanned time flagged</strong> for the PM, never blocked.</li></ul><h3 id="money" tabindex="-1">Money <a class="header-anchor" href="#money" aria-label="Permalink to &quot;Money&quot;">​</a></h3><ul><li><strong>A monthly P&amp;L</strong> with revenue, cost, profit, contribution margin and labor efficiency ratio.</li><li><strong>Cut by client, by discipline and by PM.</strong></li><li><strong>Estimates against actuals</strong> by project, client and discipline.</li><li><strong>Your own target labor efficiency ratio</strong>, company-wide or per project, with every figure colored against it.</li><li><strong>Cost from each person&#39;s rate on the date of the entry</strong>, with the full rate history kept.</li><li><strong>Fixed-fee vendors</strong> costed at their agreed fee, accrued over the project, not at an hourly rate.</li><li><strong>A forward forecast</strong> of revenue and cost, with what-if scenarios for proposals you might win.</li><li><strong>Time approval for time-and-materials projects</strong>: write hours down before they&#39;re billed, without changing what was recorded.</li><li><strong>CSV export</strong> of every time entry.</li></ul><h3 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to &quot;Proposals&quot;">​</a></h3><ul><li><strong>Cost a proposal before you send it</strong>: staffing by person or discipline, vendor fees, and the margin it will earn.</li><li><strong>Check it against capacity</strong>: can the team actually take this on, week by week?</li><li><strong>Convert a won proposal</strong> into a real project, with its tasks and client in place.</li></ul><h3 id="people" tabindex="-1">People <a class="header-anchor" href="#people" aria-label="Permalink to &quot;People&quot;">​</a></h3><ul><li><strong>Roles</strong>: owner, admin, manager and team member, each seeing exactly what they should.</li><li><strong>Managers see percentages and their own projects</strong>, never pay rates or what anyone costs.</li><li><strong>Team members see their own time</strong> and nothing else.</li><li><strong>Salary bands by discipline and level</strong>, compared against each person&#39;s pay, owners only.</li><li><strong>Contributions over time</strong> for each person, against their own capacity.</li></ul><h3 id="the-daily-rhythm" tabindex="-1">The daily rhythm <a class="header-anchor" href="#the-daily-rhythm" aria-label="Permalink to &quot;The daily rhythm&quot;">​</a></h3><ul><li><strong>A morning briefing for everyone</strong>: what to log against today, how much room is left, and last week&#39;s time.</li><li><strong>For owners and managers, the same summary as the home page</strong>: projects off course or still needing setup, who&#39;s over capacity, and for owners, last month&#39;s money.</li><li><strong>One inbox for everything waiting on you</strong>: time-off requests, time approvals, and items flagged for attention, grouped by kind.</li><li><strong>A home page brief</strong> that answers &quot;how are we doing?&quot; in one screen.</li></ul><h3 id="running-vera" tabindex="-1">Running VERA <a class="header-anchor" href="#running-vera" aria-label="Permalink to &quot;Running VERA&quot;">​</a></h3><ul><li><strong>Set up for you</strong> in about a day.</li><li><strong>A web console</strong>, no installs, that works on a phone browser.</li><li><strong>Slack is optional.</strong> Teams without it get every message by email.</li><li><strong>An audit log</strong> of everything created and every change to recorded time.</li><li><strong>A status page</strong> showing whether every part of VERA is working.</li></ul><h2 id="see-it" tabindex="-1">See it <a class="header-anchor" href="#see-it" aria-label="Permalink to &quot;See it&quot;">​</a></h2><p>The <a href="/in-action.html">See it in action</a> page shows the real console with invented data, generated by the same code that runs the product.</p><p><a href="https://calendly.com/getvera" target="_blank" rel="noreferrer"><strong>Book a 30-minute call →</strong></a></p>',24))])}const v=a(d,[["render",g]]);export{w as __pageData,v as default};
